arguments.argument:
// 放屁開始タイミングでアラーム0セット
if( global.farting_time > 0 && alarm[0] == -1 && shakable ){
//  alarm[0] = room_speed / 10 + random(room_speed / 10);
  alarm[0] = global.farting_time + room_speed / 5;
  shake_zoom = global.img_scale * (1+global.shake/200);
}

// farting_timeを消費しきらずに放屁終了した場合、アラーム再設定
else if( global.farting_time <= 0 && alarm[0] > room_speed/2 && shakable ){
  alarm[0] = room_speed / 4;
}

// アラーム0がセットされてたら画面揺らす
if( alarm[0] > 0 ){
  var svalue, svalue2, nvalue;
  if( global.shake_synchro ){
    nvalue = sin((alarm[0])*pi/2*global.shake_speed* get_sound_level()) * (1+global.shake/100);
    svalue = sin(random(alarm[0])*pi/2*global.shake_speed * get_sound_level()) * global.shake * get_sound_level();
    svalue2 = sin(random(alarm[0])*pi/2*global.shake_speed * get_sound_level()) * global.shake * get_sound_level();
  }else{
    nvalue = sin((alarm[0])*pi/2*global.shake_speed) * global.shake;
    svalue = sin(random(alarm[0])*pi/2*global.shake_speed) * global.shake;
    svalue2 = sin(random(alarm[0])*pi/2*global.shake_speed) * global.shake;
  }
  // 縦揺れ
  if( shakable == 1 ){
    background_y[0] = svalue + global.delta_y;
  }

  // 横揺れ
  else if( shakable == 2 ){
    background_x[0] = svalue + global.delta_x;
  }

  // ズーム揺れ
  else if( shakable == 3 ){
    shake_zoom = global.img_scale * (1+nvalue/100);
    fit_window_size_to_image(background_index[0], shake_zoom);
  }

  // ランダム揺れ
  else if( shakable == 4 ){
    background_x[0] = svalue + global.delta_x;
    background_y[0] = svalue2 + global.delta_y;
  }
  
}
